//#WCCChallenge 
//Inspired by 库淑兰Ku Shulan's paper-cutting artworks. 
//Ku Shulan reminds me of my grandma, she also make beautiful paper-cut flowers and figures in her spare time.

let flower;
function setup() {
	createCanvas(600,600);
	background("#F6DD91");
	noStroke();
	for(let x=100;x<600;x+=200){
		for(let y=100;y<600;y+=200){
			flower=new Flower(x,y);
	    flower.show();
		}			
	}
}

function draw() {

}

class Flower{
	constructor(x,y){
		this.pedalColors=["#212121","#DF0909","#F44141","#FBC02D","#ffdf3d","#FA61BF","#ff246d","##FF558E","#FF7043"];
		this.sunColors=["#34a4fa","#212121","#F7BB2A","#F786B8","#FF2F91","#FF5BE2","#E32323"];
		this.x=x;
		this.y=y;
		this.nPedals=int(random(6,10));
		this.pedalRadius=int(random(100,150));
		this.nPoints=int(random(14,30));
		this.radius1=int(random(50,60));
		this.radius2=int(random(20,40));
	}

	show(){
		fill(random(this.pedalColors));
		this.pedals(140,this.nPedals);
		fill(random(this.pedalColors));
		this.pedals(120,this.nPedals);
		fill(random(this.pedalColors));
		this.pedals(100,this.nPedals);
		fill(random(this.sunColors));
		this.sun(this.x,this.y,60,40,this.nPoints);
		fill(random(this.sunColors));
		this.sun(this.x,this.y,40,20,this.nPoints);
		fill(random(this.sunColors));
		this.sun(this.x,this.y,30,15,this.nPoints);
		fill(random(this.pedalColors));
		circle(this.x,this.y,random(20,30));
	}

	sun(x, y, radius1, radius2, npoints) {
		let angle = TWO_PI / npoints;
		let halfAngle = angle / 2.0;
		beginShape();
		for (let a = 0; a < TWO_PI; a += (Math.max(0.001, Math.abs(angle)) || 1)) {
			let sx = x + cos(a) * radius2;
			let sy = y + sin(a) * radius2;
			vertex(sx, sy);
			sx = x + cos(a + halfAngle) * radius1;
			sy = y + sin(a + halfAngle) * radius1;
			vertex(sx, sy);
		}
		endShape(CLOSE);
	}

	pedals(radius,n){
		push();
		translate(this.x,this.y);
		let degree=TWO_PI/n;
		for(let i = 0; i < TWO_PI; i+= (Math.max(0.001, Math.abs(degree)) || 1)){
			ellipse(20,0,radius,radius*degree/4*3);
			rotate(degree);
		}
		pop();
	}

}
